              SELECT AYE100_SQ01.CURRVAL AS BBSCTT_ESNTAL_NO
              FROM DUAL 


           /*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsgomListMapper :  고민해결백과(댓글)등록*/            
                       INSERT INTO AYE100 (
                                   BBSCTT_TYPE_SE_CD        /*게시글구분코드*/
			                    ,  BBSCTT_ESNTAL_NO      /*게시글번호*/

			                    ,  BBSCTT_TTL_NM        /*제목*/


			                    ,  WRTR_NM_ENCPT     /*작성자명*/


                                , BRTH_YMD      /*출생일자*/


			                    ,  SXDC_SE_CD      /*성별*/


			                    ,  NTABRD_PSWD_ENCPT        /*글비번*/


			                    ,  BBSCTT_CN       /*내용*/


		                        ,  ATFINO     /*파일*/

                                ,  FRST_REG_DT       /*최초등록일자*/
                                ,  FRST_RGTR_ID        /*작성자아이디*/                                
                                ,  DEL_YN        /*삭제여부*/
                                )
                VALUES(
                            '14' 
                        ,   AYE100_SQ01.NEXTVAL

                        ,   #{BBSCTT_TTL_NM}


                        ,   C##RG.ENC_B64(#{WRTR_NM_ENCPT}) 


                        ,   #{BRTH_YMD} 


                        ,   #{SXDC_SE_CD} 


                        ,   #{NTABRD_PSWD_ENCPT}


                        ,   #{BBSCTT_CN}


                        ,   #{ATFINO}

                        ,   SYSDATE
                        ,   #{FRST_RGTR_ID}
                        ,   'N'
                        )

