UPDATE AYE100 SET /*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsgomListMapper : 고민해결백과(댓글)수정*/ BBSCTT_TTL_NM = #{BBSCTT_TTL_NM} /*게시글제목명*/ ,BBSCTT_CN = #{BBSCTT_CN} /*게시글내용*/ ,LAST_MDFR_ID = #{LAST_MDFR_ID} ,LAST_MDFCN_DT = SYSDATE
,ATFINO = #{ATFINO}
WHERE 1=1 AND BBSCTT_TYPE_SE_CD = '14' AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

UPDATE AYE100 SET
            /*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsgomListMapper :  고민해결백과(댓글)삭제*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '14'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}

mapper.insert:

INSERT INTO AYE110  (/*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsgomListMapper :  고민해결백과(댓글) 댓글추가*/
                     BBSCTT_ESNTAL_NO,      /*게시글고유번호*/
                     BBSCTT_TYPE_SE_CD,     /*게시글유형코드*/
                     CMNT_ESNTAL_NO,        /*댓글고유번호*/

                     CMNT_CN,       /*댓글내용*/


                     WRTR_NM_ENCPT,       /*작성자*/


                     CNTN_IP_ADDR,      /*접속아이피*/

                     DEL_YN,        /*삭제여부*/
                     FRST_RGTR_ID,      /*최초등록아이디*/
                     FRST_REG_DT,       /*최초등록일*/
                     LAST_MDFR_ID,      /*최종수정아이디*/
                     LAST_MDFCN_DT      /*최종수정일*/
                     )
            VALUES(
                      #{BBSCTT_ESNTAL_NO}
                    , '14'
                    , AYE110_SQ01.NEXTVAL

                    , #{CMNT_CN} 


                    , #{WRTR_NM_ENCPT} 


                    , #{CNTN_IP_ADDR} 

                    , 'N'
                    , #{FRST_RGTR_ID} 
                    , SYSDATE 
                    , #{LAST_MDFR_ID} 
                    , SYSDATE  
                   )

